import React, { useState, useEffect } from 'react';
import {
  Typography, Paper, Button, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, IconButton, Dialog,
  DialogTitle, DialogContent, DialogActions, TextField, Box,
  Alert, FormControl, InputLabel, Select, MenuItem, Chip,
  Grid, Checkbox, List, ListItem, ListItemText, Divider
} from '@mui/material';
import { Add, Edit, Delete, People, SupervisorAccount, Engineering } from '@mui/icons-material';
import { realChecklistService } from '../../services/realApiService';
import api from '../../services/api';

const UsersManagement = () => {
  const [users, setUsers] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [openSupervisorDialog, setOpenSupervisorDialog] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [selectedSupervisor, setSelectedSupervisor] = useState(null);
  const [newUser, setNewUser] = useState({ 
    username: '', 
    password: '',
    name: '', 
    role: 'operator', 
    is_active: true
  });
  const [availableOperators, setAvailableOperators] = useState([]);
  const [selectedOperators, setSelectedOperators] = useState([]);
  const [assignedOperators, setAssignedOperators] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const loadData = async () => {
    try {
      setLoading(true);
      const response = await realChecklistService.getUsers();
      if (response.data.success) {
        setUsers(response.data.users);
      }
    } catch (error) {
      setError('Error cargando usuarios: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

   const loadSupervisorOperators = async (supervisorId) => {
    try {
      console.log(`🔍 Cargando operadores asignados al supervisor ID: ${supervisorId}`);
      const response = await api.get(`/api/supervisors/${supervisorId}/operators`);
      
      console.log('📋 Respuesta operadores asignados:', response.data);
      
      if (response.data.success) {
        setAssignedOperators(response.data.operators || []);
        setSelectedOperators(response.data.operators.map(op => op.id) || []);
        console.log(`✅ ${response.data.operators.length} operadores asignados cargados`);
      }
    } catch (error) {
      console.error('❌ Error cargando operadores asignados:', error);
      setAssignedOperators([]);
    }
  };

  const loadAvailableOperators = async (supervisorId) => {
    try {
      console.log(`🔍 Cargando operadores disponibles para supervisor ID: ${supervisorId}`);
      const response = await api.get(`/api/supervisors/${supervisorId}/available-operators`);
      
      console.log('📋 Respuesta operadores disponibles:', response.data);
      
      if (response.data.success) {
        setAvailableOperators(response.data.operators || []);
        console.log(`✅ ${response.data.operators.length} operadores disponibles cargados`);
        
        // DEBUG: Mostrar en consola los operadores cargados
        if (response.data.operators && response.data.operators.length > 0) {
          console.log('📝 Operadores disponibles:');
          response.data.operators.forEach(op => {
            console.log(`   - ${op.name} (ID: ${op.id}, Usuario: ${op.username})`);
          });
        }
      }
    } catch (error) {
      console.error('❌ Error cargando operadores disponibles:', error);
      setAvailableOperators([]);
      setError('Error cargando operadores disponibles: ' + error.message);
    }
  };

  const handleCreateUser = async () => {
    try {
      if (!newUser.username || !newUser.password || !newUser.name) {
        setError('Usuario, contraseña y nombre son obligatorios');
        return;
      }

      const response = await realChecklistService.createUser(newUser);
      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        resetForm();
        setError('');
      }
    } catch (error) {
      setError('Error creando usuario: ' + error.message);
    }
  };

  const handleUpdateUser = async () => {
    try {
      const userData = {
        username: newUser.username,
        name: newUser.name,
        role: newUser.role,
        is_active: newUser.is_active
      };

      if (newUser.password) {
        userData.password = newUser.password;
      }

      const response = await realChecklistService.updateUser(editingUser.id, userData);
      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        resetForm();
        setError('');
      }
    } catch (error) {
      setError('Error actualizando usuario: ' + error.message);
    }
  };

  const handleManageSupervisor = async (user) => {
    console.log('🔄 Abriendo diálogo de supervisor para:', user);
    setSelectedSupervisor(user);
    setOpenSupervisorDialog(true);
    
    // Cargar datos después de abrir el diálogo
    try {
      console.log('📥 Cargando datos del supervisor ID:', user.id);
      
      const [assignedResponse, availableResponse] = await Promise.all([
        api.get(`/api/supervisors/${user.id}/operators`),
        api.get(`/api/supervisors/${user.id}/available-operators`)
      ]);
      
      console.log('✅ Respuestas recibidas:');
      console.log('   Asignados:', assignedResponse.data);
      console.log('   Disponibles:', availableResponse.data);
      
      if (assignedResponse.data.success) {
        setAssignedOperators(assignedResponse.data.operators || []);
        setSelectedOperators(assignedResponse.data.operators.map(op => op.id) || []);
      }
      
      if (availableResponse.data.success) {
        setAvailableOperators(availableResponse.data.operators || []);
      }
      
    } catch (error) {
      console.error('❌ Error cargando datos del supervisor:', error);
      setError('Error cargando operadores: ' + error.message);
      
      // Resetear en caso de error
      setAssignedOperators([]);
      setAvailableOperators([]);
      setSelectedOperators([]);
    }
  };

  const handleAssignOperators = async () => {
    try {
      const response = await api.post(
        `/api/supervisors/${selectedSupervisor.id}/operators`,
        { operatorIds: selectedOperators }
      );
      
      if (response.data.success) {
        await loadData();
        setOpenSupervisorDialog(false);
        resetForm();
        alert(`${response.data.assignedCount} operadores asignados a ${selectedSupervisor.name}`);
      }
    } catch (error) {
      setError('Error asignando operadores: ' + error.message);
    }
  };

    const handleRefreshOperators = async () => {
    if (!selectedSupervisor) return;
    
    try {
      console.log('🔄 Refrescando operadores para supervisor:', selectedSupervisor.id);
      
      const [assignedResponse, availableResponse] = await Promise.all([
        api.get(`/api/supervisors/${selectedSupervisor.id}/operators`),
        api.get(`/api/supervisors/${selectedSupervisor.id}/available-operators`)
      ]);
      
      if (assignedResponse.data.success) {
        setAssignedOperators(assignedResponse.data.operators || []);
        setSelectedOperators(assignedResponse.data.operators.map(op => op.id) || []);
      }
      
      if (availableResponse.data.success) {
        setAvailableOperators(availableResponse.data.operators || []);
      }
      
      console.log('✅ Datos refrescados');
      
    } catch (error) {
      console.error('Error refrescando operadores:', error);
    }
  };

  const resetForm = () => {
    setEditingUser(null);
    setSelectedSupervisor(null);
    setNewUser({ 
      username: '', 
      password: '',
      name: '', 
      role: 'operator', 
      is_active: true
    });
    setSelectedOperators([]);
    setAssignedOperators([]);
    setAvailableOperators([]);
  };

  const roles = [
    { value: 'admin', label: 'Administrador', icon: <People /> },
    { value: 'supervisor', label: 'Supervisor', icon: <SupervisorAccount /> },
    { value: 'operator', label: 'Operador', icon: <Engineering /> }
  ];

  const getRoleColor = (role) => {
    switch(role) {
      case 'admin': return 'error';
      case 'supervisor': return 'warning';
      case 'operator': return 'success';
      default: return 'default';
    }
  };

  // Verificar si hay operadores en el sistema
  const hasOperators = users.some(user => user.role === 'operator' && user.is_active);

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">Gestión de Usuarios</Typography>
        <Button variant="contained" startIcon={<Add />} onClick={() => {
          resetForm();
          setOpenDialog(true);
        }}>
          Nuevo Usuario
        </Button>
      </Box>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      {!hasOperators && (
        <Alert severity="info" sx={{ mb: 2 }}>
          No hay operadores en el sistema. Crea usuarios con rol "Operador" para poder asignarlos a supervisores.
        </Alert>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Usuario</TableCell>
              <TableCell>Nombre</TableCell>
              <TableCell>Rol</TableCell>
              <TableCell>Estado</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={5} align="center">Cargando...</TableCell></TableRow>
            ) : users.map((user) => (
              <TableRow key={user.id}>
                <TableCell>{user.username}</TableCell>
                <TableCell>{user.name}</TableCell>
                <TableCell>
                  <Chip 
                    label={user.role} 
                    color={getRoleColor(user.role)}
                    size="small"
                    icon={roles.find(r => r.value === user.role)?.icon}
                  />
                </TableCell>
                <TableCell>
                  <Chip 
                    label={user.is_active ? 'Activo' : 'Inactivo'} 
                    color={user.is_active ? 'success' : 'error'}
                    size="small"
                  />
                </TableCell>
                <TableCell>
                  <IconButton size="small" onClick={() => {
                    setEditingUser(user);
                    setNewUser({...user, password: ''});
                    setOpenDialog(true);
                  }}>
                    <Edit />
                  </IconButton>
                  
                  {user.role === 'supervisor' && (
                    <IconButton 
                      size="small" 
                      color="secondary"
                      onClick={() => handleManageSupervisor(user)}
                      title="Gestionar Operadores"
                    >
                      <People />
                    </IconButton>
                  )}
                  
                  <IconButton 
                    size="small" 
                    color="error"
                    onClick={() => {
                      if (window.confirm(`¿Eliminar usuario ${user.name}?`)) {
                        realChecklistService.deleteUser(user.id).then(loadData);
                      }
                    }}
                  >
                    <Delete />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Diálogo para crear/editar usuario */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          {editingUser ? 'Editar Usuario' : 'Nuevo Usuario'}
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Selecciona los operadores que serán supervisados por {selectedSupervisor?.name}
          </Typography>
          
          {/* DEBUG INFO */}
          <Box sx={{ mb: 2, p: 1, bgcolor: '#f5f5f5', borderRadius: 1 }}>
            <Typography variant="caption" display="block">
              <strong>DEBUG INFO:</strong> Supervisor ID: {selectedSupervisor?.id}
            </Typography>
            <Typography variant="caption" display="block">
              Disponibles cargados: {availableOperators.length} | 
              Asignados cargados: {assignedOperators.length} | 
              Seleccionados: {selectedOperators.length}
            </Typography>
          </Box>
          
          {availableOperators.length === 0 && assignedOperators.length === 0 ? (
            <Alert severity="warning" sx={{ my: 2 }}>
              No hay operadores disponibles para asignar. 
              <br />
              <strong>Posibles causas:</strong>
              <ul>
                <li>No hay usuarios con rol "Operador" en el sistema</li>
                <li>Los operadores están inactivos (is_active = false)</li>
                <li>Error al cargar los datos (revisa la consola F12)</li>
              </ul>
            </Alert>
          ) : (
            <>
              {/* OPERADORES DISPONIBLES */}
              {availableOperators.length > 0 && (
                <>
                  <Typography variant="subtitle2" sx={{ mt: 2, mb: 1 }}>
                    Operadores Disponibles ({availableOperators.length}):
                  </Typography>
                  <List dense sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid #e0e0e0', borderRadius: 1 }}>
                    {availableOperators.map((operator) => (
                      <ListItem key={operator.id} divider dense>
                        <Checkbox
                          size="small"
                          checked={selectedOperators.includes(operator.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedOperators([...selectedOperators, operator.id]);
                            } else {
                              setSelectedOperators(selectedOperators.filter(id => id !== operator.id));
                            }
                          }}
                        />
                        <ListItemText
                          primary={`${operator.name} (ID: ${operator.id})`}
                          secondary={`Usuario: ${operator.username} | Estado: ${operator.is_active ? 'Activo' : 'Inactivo'}`}
                        />
                      </ListItem>
                    ))}
                  </List>
                </>
              )}
              
              {/* OPERADORES YA ASIGNADOS */}
              {assignedOperators.length > 0 && (
                <>
                  <Typography variant="subtitle2" sx={{ mt: 3, mb: 1 }}>
                    Operadores Actualmente Asignados ({assignedOperators.length}):
                  </Typography>
                  <List dense sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid #e0e0e0', borderRadius: 1 }}>
                    {assignedOperators.map((operator) => (
                      <ListItem key={operator.id} divider dense>
                        <Checkbox
                          size="small"
                          checked={selectedOperators.includes(operator.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedOperators([...selectedOperators, operator.id]);
                            } else {
                              setSelectedOperators(selectedOperators.filter(id => id !== operator.id));
                            }
                          }}
                        />
                        <ListItemText
                          primary={`${operator.name} (ID: ${operator.id})`}
                          secondary={`Usuario: ${operator.username} | Estado: ${operator.is_active ? 'Activo' : 'Inactivo'}`}
                        />
                      </ListItem>
                    ))}
                  </List>
                </>
              )}
            </>
          )}
          
          <Divider sx={{ my: 2 }} />
          
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="body2">
              Total seleccionados: <strong>{selectedOperators.length}</strong> operadores
            </Typography>
            <Button 
              size="small" 
              onClick={() => setSelectedOperators([])}
              disabled={selectedOperators.length === 0}
            >
              Limpiar selección
            </Button>
          </Box>
          
          {/* BOTÓN DE DEBUG */}
          <Box sx={{ mt: 2, textAlign: 'center' }}>
            <Button 
              size="small" 
              variant="outlined"
              onClick={() => {
                console.log('=== DEBUG INFO ===');
                console.log('Supervisor:', selectedSupervisor);
                console.log('Operadores disponibles:', availableOperators);
                console.log('Operadores asignados:', assignedOperators);
                console.log('IDs seleccionados:', selectedOperators);
                console.log('=== FIN DEBUG ===');
              }}
            >
              Mostrar Debug en Consola
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancelar</Button>
          <Button 
            variant="contained" 
            onClick={editingUser ? handleUpdateUser : handleCreateUser}
            disabled={!newUser.username || !newUser.name || (!editingUser && !newUser.password)}
          >
            {editingUser ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo para gestionar operadores de supervisor */}
      <Dialog open={openSupervisorDialog} onClose={() => setOpenSupervisorDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <SupervisorAccount />
            Operadores de {selectedSupervisor?.name}
          </Box>
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Selecciona los operadores que serán supervisados por {selectedSupervisor?.name}
          </Typography>
          
          {availableOperators.length === 0 ? (
            <Alert severity="warning" sx={{ my: 2 }}>
              No hay operadores disponibles para asignar. 
              {hasOperators ? ' Todos los operadores ya están asignados a este supervisor.' : ' Crea usuarios con rol "Operador".'}
            </Alert>
          ) : (
            <>
              <Typography variant="subtitle2" sx={{ mt: 2, mb: 1 }}>
                Operadores Disponibles ({availableOperators.length}):
              </Typography>
              <List dense sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid #e0e0e0', borderRadius: 1 }}>
                {availableOperators.map((operator) => (
                  <ListItem key={operator.id} divider dense>
                    <Checkbox
                      size="small"
                      checked={selectedOperators.includes(operator.id)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedOperators([...selectedOperators, operator.id]);
                        } else {
                          setSelectedOperators(selectedOperators.filter(id => id !== operator.id));
                        }
                      }}
                    />
                    <ListItemText
                      primary={operator.name}
                      secondary={`Usuario: ${operator.username}`}
                    />
                  </ListItem>
                ))}
              </List>
            </>
          )}
          
          {assignedOperators.length > 0 && (
            <>
              <Typography variant="subtitle2" sx={{ mt: 3, mb: 1 }}>
                Operadores Actualmente Asignados ({assignedOperators.length}):
              </Typography>
              <List dense sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid #e0e0e0', borderRadius: 1 }}>
                {assignedOperators.map((operator) => (
                  <ListItem key={operator.id} divider dense>
                    <Checkbox
                      size="small"
                      checked={selectedOperators.includes(operator.id)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedOperators([...selectedOperators, operator.id]);
                        } else {
                          setSelectedOperators(selectedOperators.filter(id => id !== operator.id));
                        }
                      }}
                    />
                    <ListItemText
                      primary={operator.name}
                      secondary={`Usuario: ${operator.username}`}
                    />
                  </ListItem>
                ))}
              </List>
            </>
          )}
          
          <Divider sx={{ my: 2 }} />
          
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="body2">
              Total seleccionados: <strong>{selectedOperators.length}</strong> operadores
            </Typography>
            <Button 
              size="small" 
              onClick={() => setSelectedOperators([])}
              disabled={selectedOperators.length === 0}
            >
              Limpiar selección
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSupervisorDialog(false)}>Cancelar</Button>
          <Button 
            variant="contained"
            onClick={handleAssignOperators}
          >
            Guardar Asignaciones
          </Button>
        </DialogActions>
                <DialogActions>
          <Button onClick={() => setOpenSupervisorDialog(false)}>Cancelar</Button>
          <Button 
            size="small"
            onClick={handleRefreshOperators}
            title="Refrescar lista"
          >
            Refrescar
          </Button>
          <Button 
            variant="contained"
            onClick={handleAssignOperators}
          >
            Guardar Asignaciones
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default UsersManagement;
